able{width:100%;border-collapse:collapse;min-width:680px}th{text-align:left;padding:11px 10px;color:#71839f;font-size:9px;text-transform:uppercase;letter-spacing:.08em;border-bottom:1px solid var(--line)}td{padding:13px 10px;border-bottom:1px solid rgba(152,177,220,.09);font-size:11px;color:#c1cde0;vertical-align:middle}tr:last-child td{border-bottom:0}.version b{display:block;color:#edf3ff}.version span{display:block;color:#8293ad;font-size:10px;margin-top:4px}.hash{font:10px monospace;color:#8ea5c8;max-width:150px;overflow:hidden;text-overflow:ellipsis}.actions{display:flex;gap:6px;flex-wrap:wrap}.tiny{padding:7px 9px;border:1px solid var(--line);border-radius:7px;background:#101a2a;color:#a8c2ef;font-size:10px;cursor:pointer}.tiny.primary{background:#2459bd;color:white}.tiny:disabled{opacity:.35;cursor:not-allowed}.empty{text-align:center;padding:38px 15px;color:#8c9cb5;font-size:11px;line-height:1.7}.empty b{display:block;color:#dce7fa;font:600 14px 'Space Grotesk',sans-serif;margin-bottom:7px}.footnote{text-align:center;color:#667895;font-size:10px;margin-top:18px}
